    (SP P D : Z) (pl : list Z) (lo : Z) (m : fmem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s7 t3 t4 t5 t6 : word) (flags : Z) (m' : fmem),
    ms' = MS (mkR (Z_to_bv 64 PC_HB_EXIT_RA) (Z_to_bv 64 SP) gp tp t0 t1 t2 (Z_to_bv 64 P) (Z_to_bv 64 D)
                  (Z_to_bv 64 (DT_BYTES (hp_mtl (huf_draws pl (zlen pl))))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (hp_streams (huf_draws pl (zlen pl)))) (Z_to_bv 64 (hp_symbols (huf_draws pl (zlen pl))))
                  (Z_to_bv 64 flags) (Z_to_bv 64 1) (Z_to_bv 64 (hp_dbuf (huf_draws pl (zlen pl)))) s7
                  s8 (Z_to_bv 64 (hp_mtl (huf_draws pl (zlen pl)))) s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 PFUZZ_MALLOC_HB) fc None m' (seg_rom psegs)
    /\ 0 <= flags < 64
    /\ munch [(P + 8, P + 16); (SP - 32, SP)] m m' /\ wmono psegs m m' /\ mem_inv psegs m'
    /\ stk psegs m' lo SP
    /\ prod_at m' P D (hp_rest (huf_draws pl (zlen pl))).

